import { useState } from 'react';
import { Menu as MenuIcon, X } from 'lucide-react';
import Menu from './components/Menu';
import Reservations from './components/Reservations';
import Faq from './components/Faq';

export default function App() {
  const [menuOpen, setMenuOpen] = useState(false);
  const links = [
    { label: "Menu", href: "#menu" },
    { label: "Reservations", href: "#reservations" },
    { label: "FAQ", href: "#faq" },
  ];
  return (
    <div className="min-h-screen bg-white text-slate-900">
      <header className="sticky top-0 z-50 bg-white/85 backdrop-blur-xl border-b border-slate-200/70">
        <div className="max-w-6xl mx-auto px-6 h-16 flex items-center justify-between">
          <a href="#top" className="flex items-center gap-2">
            <span className="w-8 h-8 rounded-xl bg-gradient-to-br from-indigo-600 to-violet-600 inline-block" />
            <span className="font-extrabold text-lg tracking-tight">Casa Verde</span>
          </a>
          <nav className="hidden md:flex items-center gap-8 text-sm font-medium text-slate-600">
            {links.map(l => <a key={l.href} href={l.href} className="hover:text-slate-900 transition-colors">{l.label}</a>)}
          </nav>
          <div className="hidden md:flex items-center gap-3">
            <a href="#top" className="px-4 py-2 rounded-xl bg-slate-900 text-white text-sm font-semibold hover:bg-slate-700 transition-colors">Get started</a>
          </div>
          <button className="md:hidden p-2" onClick={() => setMenuOpen(!menuOpen)} aria-label="Menu">
            {menuOpen ? <X className="w-5 h-5" /> : <MenuIcon className="w-5 h-5" />}
          </button>
        </div>
        {menuOpen && (
          <div className="md:hidden border-t border-slate-200 bg-white px-6 py-4 space-y-3">
            {links.map(l => <a key={l.href} href={l.href} onClick={() => setMenuOpen(false)} className="block font-medium text-slate-700">{l.label}</a>)}
          </div>
        )}
      </header>
      <main id="top">
      <Menu />
      <Reservations />
      <Faq />
      </main>
      <footer className="border-t border-slate-200 py-10 text-center text-sm text-slate-500">
        <span className="font-bold text-slate-700">Casa Verde</span> &copy; 2026. All rights reserved.
      </footer>
    </div>    );
}

import React, { useState } from 'react';
import { ChevronRight, Sparkles, CheckCircle2, Info, X, ShieldCheck } from 'lucide-react';

const initialFaqItems = [
  {
    id: 1,
    question: "How long does it take to get a table?",
    answer: "Our restaurant typically has wait times of 15-20 minutes during peak hours. For large parties or special occasions, we recommend booking in advance to ensure a seamless experience.",
    icon: Sparkles,
    isExpanded: false,
  },
  {
    id: 2,
    question: "Do you offer delivery services?",
    answer: "Yes, we now offer a contactless delivery service through our partnered food couriers. Orders placed online will be dispatched within 30 minutes from our kitchen.",
    icon: Sparkles,
    isExpanded: false,
  },
  {
    id: 3,
    question: "Is your restaurant wheelchair accessible?",
    answer: "Absolutely! Our dining area is fully accessible with wide corridors and elevators. We also provide assistive menus and staff trained to accommodate dietary needs.",
    icon: Sparkles,
    isExpanded: false,
  },
  {
    id: 4,
    question: "What is your current status on dine-in reservations?",
    answer: "As of today, we are operating at 50% capacity and taking dine-in reservations for groups up to 6 people. Larger parties may be accommodated with prior notice.",
    icon: Sparkles,
    isExpanded: false,
  },
  {
    id: 5,
    question: "Do you have any vegan or gluten-free options?",
    answer: "We're proud to offer a variety of plant-based and gluten-free dishes crafted with high-quality ingredients. Please inform your server upon arrival for detailed options.",
    icon: Sparkles,
    isExpanded: false,
  },
];

export default function Faq() {
  const [expandedIds, setExpandedIds] = useState(new Set());
  const [isLoading, setIsLoading] = useState(false);

  const toggleExpansion = (id) => {
    if (expandedIds.has(id)) {
      setExpandedIds((prev) => prev.delete(id));
    } else {
      setExpandedIds((prev) => prev.add(id));
    }
  };

  const handleDismiss = () => {
    setIsLoading(true);
    setTimeout(() => {
      setIsLoading(false);
    }, 1500);
  };

  return (
    <div className="min-h-[80vh] bg-slate-950 text-slate-100 p-4 sm:p-6 lg:p-8">
      <div className="mx-auto max-w-7xl">
        {/* Header with Sparkle decoration */}
        <div className="flex items-center justify-between px-4 pb-6 sm:px-6 lg:px-8">
          <div>
            <h2 className="text-2xl font-bold tracking-tight text-white">Frequently Asked Questions</h2>
            <p className="text-slate-400 mt-1">Get answers to the most common inquiries about dining at Casa Verde.</p>
          </div>
          <div className="flex items-center gap-2">
            {isLoading ? (
              <div className="h-8 w-8 animate-spin rounded-full bg-gradient-to-br from-indigo-500 via-purple-500 to-pink-500 bg-clip-border text-transparent animate-pulse" />
            ) : (
              <button
                onClick={handleDismiss}
                className="inline-flex items-center gap-1.5 rounded-lg bg-white/5 px-3.5 py-1.5 text-sm font-medium text-indigo-400 hover:bg-white/10 active:scale-95 transition-colors duration-200"
              >
                <X className="w-3.5 h-3.5" />
                Got it
              </button>
            )}
          </div>
        </div>

        {/* Main FAQ accordion */}
        <div className="mt-6 space-y-6 sm:mt-8">
          {initialFaqItems.map((item) => (
            <div
              key={item.id}
              className="group relative rounded-2xl bg-white/5 p-6 transition-all duration-300 hover:shadow-2xl hover:scale-[1.02] hover:bg-white/10"
            >
              <div className="flex items-start justify-between pb-4 sm:pb-6">
                <div className="flex items-start gap-4">
                  {item.icon({
                    className: "w-6 h-6 text-indigo-400 group-hover:text-indigo-500 transition-colors duration-200",
                  })}
                  <div>
                    <h3 className="text-lg font-semibold text-slate-100">{item.question}</h3>
                    <p className="text-slate-400 text-sm">{item.answer}</p>
                  </div>
                </div>
                {item.isExpanded ? (
                  <button
                    onClick={() => toggleExpansion(item.id)}
                    className="absolute right-4 top-4 rounded-lg bg-white/5 p-2 text-slate-400 hover:text-white hover:bg-white/10 transition-colors duration-200"
                  >
                    <ChevronRight className="w-4 h-4" />
                  </button>
                ) : (
                  <button
                    onClick={() => toggleExpansion(item.id)}
                    className="absolute right-4 top-4 rounded-lg bg-white/5 p-2 text-slate-400 hover:text-white hover:bg-white/10 transition-colors duration-200"
                  >
                    <ChevronRight className="w-4 h-4" />
                  </button>
                )}
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

import React, { useState } from 'react';
import { Calendar, Users, MapPin, Clock, Sparkles, CheckCircle2, X, ChevronRight } from 'lucide-react';

const defaultReservation = {
  name: '',
  guests: 4,
  date: '2024-02-12',
  time: '19:30',
  phone: '',
};

export default function Reservations() {
  const [formData, setFormData] = useState(defaultReservation);
  const [isLoading, setIsLoading] = useState(false);
  const [success, setSuccess] = useState(false);
  const [errors, setErrors] = useState({});
  const [validationMessages, setValidationMessages] = useState({});

  const validate = () => {
    const newErrors = {};
    if (!formData.name.trim()) newErrors.name = 'Please enter your name.';
    if (!formData.phone.trim()) newErrors.phone = 'Please enter a valid phone number.';
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!validate()) return;

    setIsLoading(true);
    setValidationMessages({});
    setTimeout(() => {
      setIsLoading(false);
      setSuccess(true);
      setFormData(defaultReservation);
    }, 1200);
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  return (
    <div className="w-full max-w-4xl mx-auto p-4 sm:p-6 bg-slate-950/90 backdrop-blur-xl border border-white/10 rounded-2xl shadow-2xl text-slate-100 font-sans">
      {/* Header and Decorative Decorations */}
      <div className="flex flex-col justify-center items-center mb-8">
        <div className="w-16 h-16 bg-gradient-to-br from-indigo-600 via-purple-600 to-pink-600 rounded-xl shadow-lg shadow-indigo-500/30 animate-pulse mb-4">
          <Sparkles className="w-10 h-10 text-white" />
        </div>
        <h2 className="text-2xl sm:text-3xl font-semibold tracking-tight text-slate-200 mb-2">
          Make a Reservation
        </h2>
        <p className="text-sm text-slate-400 max-w-md text-center">
          Discover the warmth of our cozy Italian kitchen and experience an unforgettable dining adventure.
        </p>
      </div>

      {/* Main Reservation Form */}
      <form onSubmit={handleSubmit} className="w-full max-w-md sm:max-w-xl">
        {success ? (
          <div className="p-6 bg-emerald-500/10 rounded-2xl border border-emerald-500/20 shadow-lg flex items-center gap-4 mb-8">
            <CheckCircle2 className="w-6 h-6 text-emerald-400 animate-pulse" />
            <div>
              <p className="text-sm font-medium text-slate-200">Reservation Confirmed!</p>
              <p className="text-xs text-slate-400">Thank you for choosing Casa Verde.</p>
            </div>
          </div>
        ) : (
          <>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 mb-6">
              <div className="relative group">
                <Calendar className="absolute left-3 top-3.5 text-slate-400 group-hover:text-white transition-colors duration-200" />
                <input
                  type="date"
                  name="date"
                  value={formData.date}
                  onChange={handleInputChange}
                  placeholder="Select Date"
                  required
                  className="w-full py-3 pl-10 pr-4 bg-slate-900 border border-slate-800 rounded-xl text-sm placeholder:text-slate-600 focus:ring-2 focus:ring-indigo-500/50 outline-none transition-all duration-200"
                />
              </div>
              <div className="relative group">
                <Clock className="absolute left-3 top-3.5 text-slate-400 group-hover:text-white transition-colors duration-200" />
                <select
                  name="time"
                  value={formData.time}
                  onChange={handleInputChange}
                  required
                  className="w-full py-3 pl-10 pr-4 bg-slate-900 border border-slate-800 rounded-xl text-sm placeholder:text-slate-600 focus:ring-2 focus:ring-indigo-500/50 outline-none transition-all duration-200"
                >
                  <option value="18:00">6:00 PM</option>
                  <option value="18:30">6:30 PM</option>
                  <option value="19:00">7:00 PM</option>
                  <option value="19:30">7:30 PM</option>
                  <option value="20:00">8:00 PM</option>
                  <option value="20:30">8:30 PM</option>
                  <option value="21:00">9:00 PM</option>
                </select>
              </div>
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 mb-6">
              <div className="relative group">
                <Users className="absolute left-3 top-3.5 text-slate-400 group-hover:text-white transition-colors duration-200" />
                <input
                  type="number"
                  min={1}
                  max={12}
                  name="guests"
                  value={formData.guests}
                  onChange={handleInputChange}
                  placeholder="Number of Guests"
                  required
                  className="w-full py-3 pl-10 pr-4 bg-slate-900 border border-slate-800 rounded-xl text-sm placeholder:text-slate-600 focus:ring-2 focus:ring-indigo-500/50 outline-none transition-all duration-200"
                />
              </div>
              <div className="relative group">
                <MapPin className="absolute left-3 top-3.5 text-slate-400 group-hover:text-white transition-colors duration-200" />
                <input
                  type="text"
                  name="phone"
                  value={formData.phone}
                  onChange={handleInputChange}
                  placeholder="Phone Number"
                  required
                  className="w-full py-3 pl-10 pr-4 bg-slate-900 border border-slate-800 rounded-xl text-sm placeholder:text-slate-600 focus:ring-2 focus:ring-indigo-500/50 outline-none transition-all duration-200"
                />
              </div>
            </div>
            <button
              type="submit"
              disabled={isLoading}
              className="w-full py-3 bg-indigo-600 text-slate-100 font-semibold rounded-xl hover:bg-indigo-700 transition-colors duration-200 flex items-center gap-2 justify-center"
            >
              {isLoading ? (
                <span className="w-4 h-4 border-2 border-white animate-spin-slow rounded-full" />
              ) : (
                <>
                  <Sparkles className="w-5 h-5 text-white" />
                  <span>Submit Reservation</span>
                </>
              )}
            </button>
          </>
        )}
      </form>

      {/* Validation and Field Errors */}
      {errors && (
        <div className="mt-4 p-4 rounded-xl bg-rose-500/10 border border-rose-500/20 text-rose-400 flex items-center gap-2 mb-6">
          <X className="w-5 h-5" />
          {Object.keys(errors).map((field) => (
            <p key={field}>{validationMessages[field] || errors[field]}</p>
          ))}
        </div>
      )}
    </div>
  );
}

